import { useAuth } from "@/_core/hooks/useAuth";
import { AIChatBox } from "@/components/AIChatBox";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { cn } from "@/lib/utils";
import { getBusinessDescriptionError } from "@/lib/businessValidation";
import { ContentStudio } from "@/components/ContentStudio";
import { ArrowUpRight, BarChart3, Bot, CalendarDays, Check, ChevronRight, CircleDollarSign, ClipboardList, FilePenLine, Gauge, LayoutDashboard, Lightbulb, Loader2, LogOut, Menu, Megaphone, MessageSquareText, Plus, Save, Settings, Sparkles, Target, Trash2, UserRound, X } from "lucide-react";
import { createElement, useState } from "react";
import { toast } from "sonner";

type View = "dashboard" | "campaigns" | "ai" | "content" | "insights" | "profile" | "settings";
type CampaignStatus = "draft" | "planned" | "active" | "completed";

const navigation: Array<{ id: View; label: string; icon: typeof LayoutDashboard }> = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
  { id: "campaigns", label: "Campaigns", icon: Megaphone },
  { id: "ai", label: "AI Marketing Manager", icon: Bot },
  { id: "content", label: "Content Studio", icon: FilePenLine },
  { id: "insights", label: "Insights", icon: BarChart3 },
  { id: "profile", label: "Business Profile", icon: UserRound },
  { id: "settings", label: "Settings", icon: Settings },
];

const quickActions: Array<{ label: string; copy: string; target: View; icon: any }> = [
  { label: "Create Campaign", copy: "Turn a goal into a structured, trackable campaign.", target: "campaigns", icon: Megaphone },
  { label: "Ask MASS AI", copy: "Get a personalized marketing recommendation.", target: "ai", icon: MessageSquareText },
  { label: "Generate Content", copy: "Create edit-ready marketing copy with context.", target: "content", icon: FilePenLine },
  { label: "View Insights", copy: "Add and interpret actual performance measurements.", target: "insights", icon: BarChart3 },
];

const statusStyles: Record<CampaignStatus, string> = {
  draft: "bg-slate-100 text-slate-700",
  planned: "bg-amber-50 text-amber-800",
  active: "bg-emerald-50 text-emerald-800",
  completed: "bg-indigo-50 text-indigo-800",
};

const initialCampaign = { name: "", objective: "", description: "", targetAudience: "", platform: "Instagram", startDate: "", endDate: "", budget: "", status: "draft" as CampaignStatus, generatedContent: "", notes: "" };

function formatDate(value: number | Date | null | undefined) {
  if (!value) return "—";
  return new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}
function compactNumber(value: number) { return new Intl.NumberFormat(undefined, { notation: "compact", maximumFractionDigits: 1 }).format(value); }
function numberOrNull(value: string) { const parsed = Number(value); return value.trim() && Number.isFinite(parsed) ? parsed : null; }
function dateOrNull(value: string) { const parsed = value ? new Date(`${value}T12:00:00`).getTime() : null; return parsed && !Number.isNaN(parsed) ? parsed : null; }
function formatLabel(value: string) { return value.replaceAll("_", " ").replace(/\b\w/g, letter => letter.toUpperCase()); }

export default function MassApp() {
  const { user, loading, logout } = useAuth();
  const [view, setView] = useState<View>("dashboard");
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const profileQuery = trpc.mass.business.get.useQuery(undefined, { enabled: !!user });

  if (loading || profileQuery.isLoading) return <LoadingScreen />;
  if (!user) return <SignInRequired />;
  if (!profileQuery.data) return <Onboarding onFinished={() => profileQuery.refetch()} />;

  const profile = profileQuery.data;
  const activeLabel = navigation.find(item => item.id === view)?.label ?? "MASS AI";
  return (
    <div className="min-h-screen bg-[#f7f9fc] text-slate-900">
      <aside className={cn("fixed inset-y-0 left-0 z-40 flex w-[260px] flex-col border-r border-slate-200 bg-[#071b2e] px-4 py-5 text-slate-300 transition-transform md:translate-x-0", mobileNavOpen ? "translate-x-0" : "-translate-x-full")}>
        <div className="mb-9 flex items-center justify-between px-2"><MassMark dark /><button className="md:hidden" onClick={() => setMobileNavOpen(false)} aria-label="Close navigation"><X className="h-5 w-5" /></button></div>
        <nav className="space-y-1">
          {navigation.map(item => { const Icon = item.icon; const active = item.id === view; return <button key={item.id} onClick={() => { setView(item.id); setMobileNavOpen(false); }} className={cn("flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-medium transition", active ? "bg-white/12 text-white shadow-sm" : "hover:bg-white/7 hover:text-white")}><Icon className="h-[18px] w-[18px]" />{item.label}</button>; })}
        </nav>
        <div className="mt-auto rounded-2xl border border-white/10 bg-white/5 p-3.5">
          <div className="flex items-start gap-2.5"><Sparkles className="mt-0.5 h-4 w-4 text-teal-300" /><div><p className="text-xs font-semibold text-white">Marketing loop</p><p className="mt-1 text-[11px] leading-relaxed text-slate-400">Understand, plan, create, measure, then decide the next action.</p></div></div>
        </div>
        <div className="mt-4 flex items-center gap-3 px-2 py-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-teal-300 to-blue-500 text-xs font-bold text-[#071b2e]">{(user.name || "U").slice(0, 1).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-white">{user.name || "Business owner"}</p><p className="truncate text-[11px] text-slate-400">{profile.businessName}</p></div><button onClick={logout} className="rounded-md p-1.5 text-slate-400 hover:bg-white/10 hover:text-white" aria-label="Sign out"><LogOut className="h-4 w-4" /></button></div>
      </aside>
      {mobileNavOpen && <button className="fixed inset-0 z-30 bg-slate-950/35 md:hidden" onClick={() => setMobileNavOpen(false)} aria-label="Close navigation overlay" />}
      <main className="min-h-screen md:pl-[260px]">
        <header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-slate-200/80 bg-[#f7f9fc]/85 px-4 backdrop-blur md:px-8">
          <div className="flex items-center gap-3"><button className="rounded-lg p-2 text-slate-600 hover:bg-white md:hidden" onClick={() => setMobileNavOpen(true)} aria-label="Open navigation"><Menu className="h-5 w-5" /></button><div><p className="text-xs font-medium text-slate-400">MASS AI</p><h1 className="text-base font-bold tracking-tight">{activeLabel}</h1></div></div>
          <div className="flex items-center gap-2"><span className="hidden items-center gap-1.5 rounded-full border border-teal-200 bg-teal-50 px-2.5 py-1 text-xs font-semibold text-teal-800 sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-teal-500" />Personalized workspace</span><div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-200 text-xs font-bold text-slate-700 md:hidden">{(user.name || "U").slice(0, 1).toUpperCase()}</div></div>
        </header>
        <div className="mx-auto max-w-7xl px-4 py-6 md:px-8 md:py-8">
          {view === "dashboard" && <Dashboard profile={profile} goTo={setView} />}
          {view === "campaigns" && <Campaigns />}
          {view === "ai" && <MarketingManager />}
          {view === "content" && <ContentStudio />}
          {view === "insights" && <Insights />}
          {view === "profile" && <BusinessProfile profile={profile} onFinished={() => profileQuery.refetch()} />}
          {view === "settings" && <SettingsView onProfile={() => setView("profile")} />}
        </div>
      </main>
    </div>
  );
}

function MassMark({ dark = false }: { dark?: boolean }) { return <div className="flex items-center gap-2.5"><div className="grid h-8 w-8 place-items-center rounded-lg bg-gradient-to-br from-teal-300 via-cyan-300 to-blue-500 shadow-lg shadow-cyan-400/20"><span className="text-sm font-black tracking-[-0.15em] text-[#041927]">M</span></div><div><p className={cn("text-sm font-black tracking-[-0.06em]", dark ? "text-white" : "text-[#071b2e]")}>MASS <span className="text-teal-500">AI</span></p><p className={cn("text-[9px] font-semibold uppercase tracking-[0.16em]", dark ? "text-slate-400" : "text-slate-500")}>Marketing manager</p></div></div>; }
function LoadingScreen() { return <div className="grid min-h-screen place-items-center bg-[#f7f9fc]"><div className="flex flex-col items-center gap-3 text-slate-500"><Loader2 className="h-7 w-7 animate-spin text-teal-600" /><p className="text-sm">Opening your MASS AI workspace…</p></div></div>; }
function SignInRequired() { return <div className="grid min-h-screen place-items-center bg-[#071b2e] p-5"><div className="max-w-sm rounded-3xl bg-white p-8 text-center shadow-2xl"><MassMark /><h1 className="mt-8 text-2xl font-bold tracking-tight">Your marketing command center awaits.</h1><p className="mt-3 text-sm leading-relaxed text-slate-600">Sign in to manage your business context, campaigns, content, and measured marketing insights.</p><Button className="mt-7 w-full bg-[#0f766e] hover:bg-[#0b625c]" onClick={() => startLogin()}>Sign in to MASS AI <ArrowUpRight className="ml-1 h-4 w-4" /></Button></div></div>; }

function Onboarding({ onFinished }: { onFinished: () => void }) {
  const [form, setForm] = useState({ businessName: "", businessType: "", description: "", location: "", targetAudience: "", marketingGoal: "", channels: "Instagram, WhatsApp", productsServices: "", monthlyBudget: "", websiteUrl: "", socialLinks: "" });
  const [descriptionError, setDescriptionError] = useState<string | null>(null);
  const save = trpc.mass.business.save.useMutation({ onSuccess: () => { toast.success("Your MASS AI workspace is ready."); onFinished(); }, onError: error => toast.error(error.message) });
  const submit = (event: React.FormEvent) => { event.preventDefault(); const nextDescriptionError = getBusinessDescriptionError(form.description); if (nextDescriptionError) { setDescriptionError(nextDescriptionError); toast.error("Add a more complete business description before continuing."); return; } const parsedChannels = form.channels.split(",").map(item => item.trim()).filter(Boolean); if (!parsedChannels.length) return toast.error("Add at least one preferred marketing channel."); save.mutate({ ...form, channels: parsedChannels, monthlyBudget: numberOrNull(form.monthlyBudget), websiteUrl: form.websiteUrl || null, socialLinks: form.socialLinks || null }); };
  const set = (key: keyof typeof form, value: string) => { if (key === "description") setDescriptionError(getBusinessDescriptionError(value)); setForm(current => ({ ...current, [key]: value })); };
  return <div className="min-h-screen bg-[#071b2e] px-4 py-7 md:py-12"><div className="mx-auto max-w-4xl"><MassMark dark /><div className="mt-9 grid overflow-hidden rounded-[28px] bg-white shadow-2xl md:grid-cols-[0.8fr_1.2fr]"><section className="bg-gradient-to-br from-teal-50 to-cyan-50 p-7 md:p-9"><div className="inline-flex rounded-xl bg-[#071b2e] p-2.5 text-teal-300"><Sparkles className="h-5 w-5" /></div><h1 className="mt-6 text-3xl font-bold tracking-tight text-[#071b2e]">Let’s understand your business.</h1><p className="mt-3 text-sm leading-relaxed text-slate-600">MASS AI uses this information as context for your campaigns, recommendations, content, and insight interpretation.</p><div className="mt-8 space-y-4">{[["1", "Business context", "Who you are, what you sell, and where you serve."], ["2", "Marketing focus", "Your audience, goal, budget, and preferred channels."], ["3", "Personalized workspace", "Plans and recommendations grounded in your information."]].map(([n, title, text]) => <div className="flex gap-3" key={n}><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-teal-600 text-xs font-bold text-white">{n}</span><div><p className="text-sm font-bold text-slate-800">{title}</p><p className="text-xs leading-relaxed text-slate-500">{text}</p></div></div>)}</div></section><form onSubmit={submit} className="p-7 md:p-9"><p className="text-xs font-bold uppercase tracking-[0.16em] text-teal-700">Business onboarding</p><h2 className="mt-2 text-xl font-bold">Build your marketing brief</h2><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Business name"><Input required value={form.businessName} onChange={e => set("businessName", e.target.value)} placeholder="Local Bakery" /></Field><Field label="Business type"><Input required value={form.businessType} onChange={e => set("businessType", e.target.value)} placeholder="Bakery, salon, clinic…" /></Field><Field label="Location"><Input required value={form.location} onChange={e => set("location", e.target.value)} placeholder="Austin, TX" /></Field><Field label="Monthly budget (optional)"><Input type="number" min="0" value={form.monthlyBudget} onChange={e => set("monthlyBudget", e.target.value)} placeholder="500" /></Field><Field className="sm:col-span-2" label="What does your business offer?"><Textarea required value={form.productsServices} onChange={e => set("productsServices", e.target.value)} placeholder="Fresh sourdough, celebration cakes, and weekday coffee service." /></Field><Field className="sm:col-span-2" label="Business description"><Textarea required aria-invalid={Boolean(descriptionError)} className={cn(descriptionError && "border-red-400 focus-visible:ring-red-400")} value={form.description} onChange={e => set("description", e.target.value)} placeholder="Tell MASS AI what makes the business distinctive." />{descriptionError ? <p role="alert" className="text-xs font-medium text-red-600">{descriptionError}</p> : <p className="text-xs text-slate-500">A short note is enough. Share any detail that helps describe your business.</p>}</Field><Field className="sm:col-span-2" label="Target audience"><Input required value={form.targetAudience} onChange={e => set("targetAudience", e.target.value)} placeholder="Nearby families and professionals looking for fresh baked goods" /></Field><Field label="Main marketing goal"><Input required value={form.marketingGoal} onChange={e => set("marketingGoal", e.target.value)} placeholder="Get more local customers" /></Field><Field label="Preferred channels"><Input required value={form.channels} onChange={e => set("channels", e.target.value)} placeholder="Instagram, WhatsApp" /></Field><Field label="Website (optional)"><Input type="url" value={form.websiteUrl} onChange={e => set("websiteUrl", e.target.value)} placeholder="https://…" /></Field><Field label="Social links (optional)"><Input value={form.socialLinks} onChange={e => set("socialLinks", e.target.value)} placeholder="@yourbusiness" /></Field></div><Button disabled={save.isPending} className="mt-6 w-full bg-[#0f766e] hover:bg-[#0b625c]">{save.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <ChevronRight className="mr-1 h-4 w-4" />}Create my workspace</Button></form></div></div></div>;
}

function Field({ label, children, className }: { label: string; children: React.ReactNode; className?: string }) { return <label className={cn("grid gap-1.5", className)}><span className="text-xs font-semibold text-slate-700">{label}</span>{children}</label>; }

function Dashboard({ profile, goTo }: { profile: any; goTo: (view: View) => void }) {
  const summary = trpc.mass.dashboard.summary.useQuery();
  if (summary.isLoading) return <PageLoading />;
  if (summary.error) return <ErrorState message={summary.error.message} retry={() => summary.refetch()} />;
  const data = summary.data!;
  const activeCampaigns = data.campaigns.filter((campaign: any) => campaign.status === "active");
  return <section className="space-y-7"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-sm font-medium text-teal-700">{new Date().toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })}</p><h2 className="mt-1 text-3xl font-bold tracking-tight text-[#071b2e]">Good to see you, {profile.businessName}.</h2><p className="mt-2 max-w-2xl text-sm text-slate-600">Here is the current picture of your marketing activity and the next actions MASS AI can help you take.</p></div><button onClick={() => goTo("profile")} className="inline-flex items-center gap-2 self-start rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-700 shadow-sm hover:border-teal-300 sm:self-auto"><Target className="h-4 w-4 text-teal-600" />{profile.marketingGoal}<ChevronRight className="h-4 w-4 text-slate-400" /></button></div>
  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Active campaigns" value={String(activeCampaigns.length)} detail={`${data.campaigns.length} total campaigns`} icon={Megaphone} color="teal" /><MetricCard label="Measured updates" value={String(data.metricsCount)} detail="Manually entered metrics" icon={BarChart3} color="blue" /><MetricCard label="Trial status" value={data.trial.status} detail={`${data.trial.daysRemaining} day${data.trial.daysRemaining === 1 ? "" : "s"} remaining`} icon={CalendarDays} color="amber" /><MetricCard label="Preferred channels" value={profile.channels.length.toString()} detail={profile.channels.join(", ")} icon={Gauge} color="violet" /></div>
  <div className="grid gap-6 xl:grid-cols-[1.5fr_1fr]"><div className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm md:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-teal-700">Next best actions</p><h3 className="mt-1 text-xl font-bold">Move your marketing forward</h3></div><span className="rounded-full bg-teal-50 px-2.5 py-1 text-xs font-bold text-teal-700">{profile.businessType}</span></div><div className="mt-5 grid gap-3 sm:grid-cols-2">{quickActions.map(action => <button key={action.label} onClick={() => goTo(action.target)} className="group rounded-2xl border border-slate-200 p-4 text-left transition hover:-translate-y-0.5 hover:border-teal-300 hover:shadow-md"><span className="grid h-9 w-9 place-items-center rounded-lg bg-slate-100 text-slate-700 group-hover:bg-teal-50 group-hover:text-teal-700">{createElement(action.icon, { className: "h-4 w-4" })}</span><p className="mt-4 text-sm font-bold text-slate-900">{action.label}</p><p className="mt-1 text-xs leading-relaxed text-slate-500">{action.copy}</p><span className="mt-3 inline-flex items-center text-xs font-bold text-teal-700">Open <ArrowUpRight className="ml-1 h-3 w-3" /></span></button>)}</div></div>
    <div className="rounded-3xl bg-[#071b2e] p-5 text-white shadow-sm md:p-6"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-teal-300/15 text-teal-300"><Sparkles className="h-4 w-4" /></span><p className="text-sm font-bold">MASS AI guidance</p></div><button onClick={() => goTo("ai")} className="text-xs font-bold text-teal-300 hover:text-white">Ask a question</button></div><div className="mt-5 space-y-3">{data.recommendations.length ? data.recommendations.slice(0, 2).map((recommendation: any) => <div className="rounded-xl border border-white/10 bg-white/5 p-3" key={recommendation.id}><p className="text-xs font-bold text-teal-300">{recommendation.title}</p><p className="mt-1 line-clamp-3 text-xs leading-relaxed text-slate-300">{recommendation.content.replace(/[{}\[\]"]/g, "")}</p></div>) : <div className="rounded-xl border border-dashed border-white/15 p-4"><p className="text-sm font-semibold">No guidance yet</p><p className="mt-1 text-xs leading-relaxed text-slate-400">Ask MASS AI a question, or interpret real performance data to create a tailored next-step recommendation.</p></div>}</div></div></div>
  <div className="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]"><section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm md:p-6"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-slate-500">Campaigns</p><h3 className="mt-1 text-lg font-bold">Campaign pulse</h3></div><button onClick={() => goTo("campaigns")} className="text-sm font-bold text-teal-700 hover:text-teal-900">Manage all</button></div><div className="mt-5 space-y-3">{data.campaigns.length ? data.campaigns.slice(0, 4).map((campaign: any) => <div key={campaign.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-slate-50 px-4 py-3"><div><p className="text-sm font-bold">{campaign.name}</p><p className="mt-0.5 text-xs text-slate-500">{campaign.platform || "Channel to be chosen"} · Updated {formatDate(campaign.updatedAt)}</p></div><span className={cn("rounded-full px-2.5 py-1 text-[11px] font-bold capitalize", statusStyles[campaign.status as CampaignStatus])}>{campaign.status}</span></div>) : <EmptyInline icon={Megaphone} title="No campaigns yet" text="Start with a campaign plan or create one from scratch." action="Create Campaign" onClick={() => goTo("campaigns")} />}</div></section><section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm md:p-6"><p className="text-xs font-bold uppercase tracking-[0.15em] text-slate-500">Recent activity</p><h3 className="mt-1 text-lg font-bold">Workspace history</h3><div className="mt-5 space-y-4">{data.activities.length ? data.activities.map((activity: any) => <div className="flex gap-3" key={activity.id}><span className="mt-0.5 h-2 w-2 rounded-full bg-teal-500" /><div><p className="text-sm font-medium text-slate-800">{activity.description}</p><p className="mt-0.5 text-xs text-slate-500">{formatDate(activity.createdAt)}</p></div></div>) : <EmptyInline icon={ClipboardList} title="Your activity will appear here" text="Create a campaign or save content to begin." />}</div></section></div>
  </section>;
}

function MetricCard({ label, value, detail, icon: Icon, color }: { label: string; value: string; detail: string; icon: any; color: "teal" | "blue" | "amber" | "violet" }) { const colors = { teal: "bg-teal-50 text-teal-700", blue: "bg-blue-50 text-blue-700", amber: "bg-amber-50 text-amber-700", violet: "bg-violet-50 text-violet-700" }; return <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><p className="text-xs font-semibold text-slate-500">{label}</p><span className={cn("grid h-8 w-8 place-items-center rounded-lg", colors[color])}><Icon className="h-4 w-4" /></span></div><p className="mt-4 truncate text-2xl font-bold tracking-tight text-[#071b2e]">{value}</p><p className="mt-1 truncate text-xs text-slate-500">{detail}</p></div>; }
function EmptyInline({ icon: Icon, title, text, action, onClick }: { icon: any; title: string; text: string; action?: string; onClick?: () => void }) { return <div className="rounded-xl border border-dashed border-slate-200 p-5 text-center"><Icon className="mx-auto h-5 w-5 text-slate-300" /><p className="mt-2 text-sm font-semibold text-slate-700">{title}</p><p className="mx-auto mt-1 max-w-xs text-xs leading-relaxed text-slate-500">{text}</p>{action && <button onClick={onClick} className="mt-3 text-xs font-bold text-teal-700">{action}</button>}</div>; }
function PageLoading() { return <div className="grid min-h-[45vh] place-items-center"><Loader2 className="h-6 w-6 animate-spin text-teal-600" /></div>; }
function ErrorState({ message, retry }: { message: string; retry: () => void }) { return <div className="grid min-h-[45vh] place-items-center"><div className="max-w-md rounded-2xl border border-red-100 bg-red-50 p-6 text-center"><p className="font-bold text-red-900">We could not load this workspace data.</p><p className="mt-2 text-sm text-red-700">{message}</p><Button variant="outline" onClick={retry} className="mt-4">Try again</Button></div></div>; }

function Campaigns() {
  const campaigns = trpc.mass.campaign.list.useQuery();
  const [editor, setEditor] = useState<any>(null);
  const [plannerOpen, setPlannerOpen] = useState(false);
  if (campaigns.isLoading) return <PageLoading />;
  if (campaigns.error) return <ErrorState message={campaigns.error.message} retry={() => campaigns.refetch()} />;
  return <section><PageHeading eyebrow="Campaign management" title="Plan, manage, and learn from campaigns" description="Keep your marketing initiatives grounded in a clear objective, audience, message, and status." actions={<><Button variant="outline" onClick={() => setPlannerOpen(true)}><Sparkles className="mr-2 h-4 w-4 text-teal-700" />Plan with MASS AI</Button><Button className="bg-[#0f766e] hover:bg-[#0b625c]" onClick={() => setEditor({ ...initialCampaign })}><Plus className="mr-1 h-4 w-4" />Create Campaign</Button></>} />
  <div className="mt-6 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">{campaigns.data!.length ? <div className="divide-y divide-slate-100">{campaigns.data!.map((campaign: any) => <CampaignRow key={campaign.id} campaign={campaign} refresh={() => campaigns.refetch()} edit={() => setEditor({ ...campaign, startDate: campaign.startDate ? new Date(campaign.startDate).toISOString().slice(0, 10) : "", endDate: campaign.endDate ? new Date(campaign.endDate).toISOString().slice(0, 10) : "", budget: campaign.budget ?? "" })} />)}</div> : <div className="p-12"><EmptyInline icon={Megaphone} title="Your campaign board is empty" text="Create a campaign manually or let MASS AI turn your next goal into an actionable plan." action="Create Campaign" onClick={() => setEditor({ ...initialCampaign })} /></div>}</div>
  {editor && <CampaignEditor campaign={editor} close={() => setEditor(null)} refresh={() => { campaigns.refetch(); setEditor(null); }} />}{plannerOpen && <CampaignPlanner close={() => setPlannerOpen(false)} saved={() => { campaigns.refetch(); setPlannerOpen(false); }} />}</section>;
}
function PageHeading({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: React.ReactNode }) { return <div className="flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-teal-700">{eyebrow}</p><h2 className="mt-2 text-3xl font-bold tracking-tight text-[#071b2e]">{title}</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-600">{description}</p></div>{actions && <div className="flex flex-wrap gap-2">{actions}</div>}</div>; }
function CampaignRow({ campaign, edit, refresh }: { campaign: any; edit: () => void; refresh: () => void }) { const update = trpc.mass.campaign.updateStatus.useMutation({ onSuccess: () => { toast.success("Campaign status updated."); refresh(); }, onError: e => toast.error(e.message) }); const remove = trpc.mass.campaign.remove.useMutation({ onSuccess: () => { toast.success("Campaign deleted."); refresh(); }, onError: e => toast.error(e.message) }); return <div className="grid gap-4 p-5 lg:grid-cols-[1.5fr_1fr_auto] lg:items-center"><div><div className="flex flex-wrap items-center gap-2"><p className="font-bold text-slate-900">{campaign.name}</p><span className={cn("rounded-full px-2.5 py-1 text-[11px] font-bold capitalize", statusStyles[campaign.status as CampaignStatus])}>{campaign.status}</span></div><p className="mt-1 line-clamp-1 text-sm text-slate-600">{campaign.objective}</p><p className="mt-2 text-xs text-slate-400">{campaign.platform || "No channel selected"} {campaign.budget ? `· $${campaign.budget.toLocaleString()} budget` : ""} {campaign.startDate ? `· Starts ${formatDate(campaign.startDate)}` : ""}</p></div><div className="flex items-center gap-2"><select aria-label={`Change status for ${campaign.name}`} value={campaign.status} disabled={update.isPending} onChange={e => update.mutate({ id: campaign.id, status: e.target.value as CampaignStatus })} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs font-semibold text-slate-700 focus:outline-none focus:ring-2 focus:ring-teal-500"><option value="draft">Draft</option><option value="planned">Planned</option><option value="active">Active</option><option value="completed">Completed</option></select></div><div className="flex gap-2 lg:justify-end"><Button size="sm" variant="outline" onClick={edit}>Edit</Button><Button size="sm" variant="ghost" className="text-red-600 hover:bg-red-50 hover:text-red-700" disabled={remove.isPending} onClick={() => { if (window.confirm(`Delete “${campaign.name}”? This cannot be undone.`)) remove.mutate({ id: campaign.id }); }}><Trash2 className="h-4 w-4" /></Button></div></div>; }
function CampaignEditor({ campaign, close, refresh }: { campaign: any; close: () => void; refresh: () => void }) { const [form, setForm] = useState(campaign); const create = trpc.mass.campaign.create.useMutation({ onSuccess: () => { toast.success("Campaign created."); refresh(); }, onError: e => toast.error(e.message) }); const update = trpc.mass.campaign.update.useMutation({ onSuccess: () => { toast.success("Campaign updated."); refresh(); }, onError: e => toast.error(e.message) }); const busy = create.isPending || update.isPending; const set = (key: string, value: any) => setForm((current: any) => ({ ...current, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); const data = { name: form.name, objective: form.objective, description: form.description || null, targetAudience: form.targetAudience || null, platform: form.platform || null, startDate: dateOrNull(form.startDate), endDate: dateOrNull(form.endDate), budget: numberOrNull(String(form.budget)), status: form.status as CampaignStatus, generatedContent: form.generatedContent || null, notes: form.notes || null }; if (form.id) update.mutate({ id: form.id, ...data }); else create.mutate(data); }; return <Modal title={form.id ? "Edit campaign" : "Create campaign"} close={close}><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2"><Field className="sm:col-span-2" label="Campaign name"><Input required value={form.name} onChange={e => set("name", e.target.value)} placeholder="Weekend local offer" /></Field><Field className="sm:col-span-2" label="Objective"><Textarea required value={form.objective} onChange={e => set("objective", e.target.value)} placeholder="What change should this campaign create?" /></Field><Field label="Target audience"><Input value={form.targetAudience || ""} onChange={e => set("targetAudience", e.target.value)} placeholder="Nearby weekday customers" /></Field><Field label="Primary platform"><Input value={form.platform || ""} onChange={e => set("platform", e.target.value)} placeholder="Instagram + WhatsApp" /></Field><Field label="Start date"><Input type="date" value={form.startDate || ""} onChange={e => set("startDate", e.target.value)} /></Field><Field label="End date"><Input type="date" value={form.endDate || ""} onChange={e => set("endDate", e.target.value)} /></Field><Field label="Budget"><Input type="number" min="0" value={form.budget || ""} onChange={e => set("budget", e.target.value)} placeholder="500" /></Field><Field label="Status"><select value={form.status} onChange={e => set("status", e.target.value)} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm shadow-sm"><option value="draft">Draft</option><option value="planned">Planned</option><option value="active">Active</option><option value="completed">Completed</option></select></Field><Field className="sm:col-span-2" label="Generated content or key messages"><Textarea value={form.generatedContent || ""} onChange={e => set("generatedContent", e.target.value)} placeholder="Add proposed copy or key message." /></Field><Field className="sm:col-span-2" label="Notes"><Textarea value={form.notes || ""} onChange={e => set("notes", e.target.value)} placeholder="Internal notes, dependencies, or reminders." /></Field><div className="mt-2 flex justify-end gap-2 sm:col-span-2"><Button type="button" variant="outline" onClick={close}>Cancel</Button><Button disabled={busy} className="bg-[#0f766e] hover:bg-[#0b625c]" type="submit">{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}<Save className="mr-1 h-4 w-4" />Save campaign</Button></div></form></Modal>; }
function Modal({ title, close, children }: { title: string; close: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-50 grid items-end bg-slate-950/45 p-0 sm:place-items-center sm:p-5"><div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:rounded-3xl sm:p-6"><div className="mb-6 flex items-center justify-between"><h3 className="text-xl font-bold text-[#071b2e]">{title}</h3><button className="rounded-lg p-2 hover:bg-slate-100" onClick={close} aria-label="Close"><X className="h-5 w-5" /></button></div>{children}</div></div>; }
function CampaignPlanner({ close, saved }: { close: () => void; saved: () => void }) { const [form, setForm] = useState({ goal: "", product: "", audience: "", budget: "", platform: "Instagram", duration: "2 weeks" }); const [plan, setPlan] = useState<any>(null); const generate = trpc.mass.ai.planner.useMutation({ onSuccess: setPlan, onError: e => toast.error(e.message) }); const create = trpc.mass.campaign.create.useMutation({ onSuccess: () => { toast.success("Campaign plan saved as a campaign."); saved(); }, onError: e => toast.error(e.message) }); const set = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); generate.mutate({ ...form, budget: numberOrNull(form.budget) }); }; return <Modal title="Plan a campaign with MASS AI" close={close}>{!plan ? <form onSubmit={submit} className="grid gap-4 sm:grid-cols-2"><p className="text-sm leading-relaxed text-slate-600 sm:col-span-2">MASS AI will use your business context and active campaigns to create a structured, reviewable plan. Nothing will be published automatically.</p><Field label="Goal"><Input required value={form.goal} onChange={e => set("goal", e.target.value)} placeholder="Get more weekend customers" /></Field><Field label="Product or service"><Input required value={form.product} onChange={e => set("product", e.target.value)} placeholder="Seasonal cake box" /></Field><Field label="Target audience"><Input required value={form.audience} onChange={e => set("audience", e.target.value)} placeholder="Nearby families" /></Field><Field label="Budget"><Input type="number" min="0" value={form.budget} onChange={e => set("budget", e.target.value)} placeholder="500" /></Field><Field label="Platform"><Input required value={form.platform} onChange={e => set("platform", e.target.value)} /></Field><Field label="Duration"><Input required value={form.duration} onChange={e => set("duration", e.target.value)} /></Field><div className="flex justify-end sm:col-span-2"><Button disabled={generate.isPending} className="bg-[#0f766e] hover:bg-[#0b625c]">{generate.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Sparkles className="mr-2 h-4 w-4" />}Generate plan</Button></div></form> : <div><div className="rounded-2xl bg-teal-50 p-4"><p className="text-xs font-bold uppercase tracking-[0.14em] text-teal-700">Proposed campaign</p><h4 className="mt-1 text-xl font-bold text-[#071b2e]">{plan.campaignName}</h4><p className="mt-2 text-sm text-slate-700">{plan.objective}</p></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><PlanList title="Recommended channels" values={plan.recommendedChannels} /><PlanList title="Content ideas" values={plan.contentIdeas} /><PlanList title="Posting schedule" values={plan.postingSchedule} /><PlanList title="Success metrics" values={plan.successMetrics} /><PlanList title="Budget allocation" values={plan.budgetAllocation} /><div className="rounded-xl border border-slate-200 p-3"><p className="text-xs font-bold text-slate-500">Call to action</p><p className="mt-1 text-sm font-semibold">{plan.callToAction}</p></div></div><div className="mt-5 rounded-xl border-l-4 border-teal-500 bg-slate-50 p-3"><p className="text-xs font-bold text-slate-500">Key message</p><p className="mt-1 text-sm text-slate-700">{plan.keyMessage}</p></div><div className="mt-6 flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setPlan(null)}>Edit inputs</Button><Button disabled={create.isPending} className="bg-[#0f766e] hover:bg-[#0b625c]" onClick={() => create.mutate({ name: plan.campaignName, objective: plan.objective, description: plan.keyMessage, targetAudience: plan.targetAudience, platform: plan.recommendedChannels.join(", "), startDate: null, endDate: null, budget: numberOrNull(form.budget), status: "draft", generatedContent: `CTA: ${plan.callToAction}\n\nContent ideas:\n${plan.contentIdeas.map((i: string) => `• ${i}`).join("\n")}`, notes: `Posting schedule:\n${plan.postingSchedule.map((i: string) => `• ${i}`).join("\n")}\n\nSuccess metrics:\n${plan.successMetrics.map((i: string) => `• ${i}`).join("\n")}` })}><Save className="mr-1 h-4 w-4" />Save as campaign</Button></div></div>}</Modal>; }
function PlanList({ title, values }: { title: string; values: string[] }) { return <div className="rounded-xl border border-slate-200 p-3"><p className="text-xs font-bold text-slate-500">{title}</p><ul className="mt-2 space-y-1.5">{values.map((value, index) => <li key={index} className="flex gap-1.5 text-xs leading-relaxed text-slate-700"><Check className="mt-0.5 h-3 w-3 shrink-0 text-teal-600" />{value}</li>)}</ul></div>; }

function MarketingManager() { const messages = trpc.mass.ai.chatHistory.useQuery(); const send = trpc.mass.ai.chat.useMutation({ onSuccess: () => { messages.refetch(); }, onError: e => toast.error(e.message) }); if (messages.isLoading) return <PageLoading />; return <section><PageHeading eyebrow="AI Marketing Manager" title="Get guidance rooted in your business context" description="MASS AI considers your stored business profile and campaigns. It labels missing context instead of inventing business facts or guaranteed results." /><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_2fr]"><aside className="rounded-3xl bg-[#071b2e] p-5 text-white"><span className="grid h-9 w-9 place-items-center rounded-xl bg-teal-300/15 text-teal-300"><Bot className="h-5 w-5" /></span><h3 className="mt-5 text-lg font-bold">Think of MASS AI as your on-call marketing manager.</h3><p className="mt-2 text-sm leading-relaxed text-slate-300">Use it to clarify the next campaign, improve an offer, choose a channel, or interpret a practical marketing decision.</p><div className="mt-6 space-y-3 border-t border-white/10 pt-5"><p className="text-xs font-bold uppercase tracking-[0.12em] text-teal-300">How responses work</p>{[["Recommendation", "A practical next move."], ["Why", "The context behind it."], ["How to execute", "Concrete steps to test."], ["Metric to monitor", "A measurement to watch."]].map(([title, description]) => <div key={title} className="flex gap-2"><span className="mt-1.5 h-1.5 w-1.5 rounded-full bg-teal-300" /><p className="text-xs text-slate-300"><strong className="text-white">{title}:</strong> {description}</p></div>)}</div></aside><AIChatBox className="h-[600px] border-slate-200 shadow-sm" height="600px" messages={(messages.data || []) as any} onSendMessage={question => send.mutate({ question })} isLoading={send.isPending} emptyStateMessage="Ask MASS AI about your next marketing move." placeholder="Ask a question about your marketing…" suggestedPrompts={["What should we promote this week?", "How can I improve my Instagram offer?", "Which metric should I focus on first?", "Help me shape a campaign for a local audience."]} /></div></section>; }

function LegacyContentStudio() { return null; }

function Insights() { const campaigns = trpc.mass.campaign.list.useQuery(); const insights = trpc.mass.insight.list.useQuery(); const [form, setForm] = useState({ campaignId: "", metricDate: new Date().toISOString().slice(0, 10), reach: "0", impressions: "0", engagement: "0", clicks: "0", leads: "0", conversions: "0", spend: "0", notes: "" }); const [interpretations, setInterpretations] = useState<Record<number, any>>({}); const create = trpc.mass.insight.create.useMutation({ onSuccess: () => { toast.success("Actual measured data saved."); insights.refetch(); }, onError: e => toast.error(e.message) }); const interpret = trpc.mass.ai.interpretInsight.useMutation({ onSuccess: (result, variables) => { setInterpretations(current => ({ ...current, [variables.insightId]: result })); toast.success("AI interpretation created from the measured data."); }, onError: e => toast.error(e.message) }); const set = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ campaignId: form.campaignId ? Number(form.campaignId) : null, metricDate: new Date(`${form.metricDate}T12:00:00`).getTime(), reach: Number(form.reach) || 0, impressions: Number(form.impressions) || 0, engagement: Number(form.engagement) || 0, clicks: Number(form.clicks) || 0, leads: Number(form.leads) || 0, conversions: Number(form.conversions) || 0, spend: Number(form.spend) || 0, notes: form.notes || null }); }; if (campaigns.isLoading || insights.isLoading) return <PageLoading />; const latest = insights.data![0]; const rates = latest ? { engagement: latest.reach ? (latest.engagement / latest.reach) * 100 : 0, click: latest.impressions ? (latest.clicks / latest.impressions) * 100 : 0, conversion: latest.clicks ? (latest.conversions / latest.clicks) * 100 : 0 } : null; return <section><PageHeading eyebrow="Marketing Insights" title="Separate measurement from interpretation" description="Enter actual, observed performance data. MASS AI can interpret it and suggest next actions, but it never changes or substitutes the raw metrics." /><div className="mt-6 grid gap-6 xl:grid-cols-[0.85fr_1.15fr]"><form onSubmit={submit} className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-2"><span className="grid h-8 w-8 place-items-center rounded-lg bg-blue-50 text-blue-700"><BarChart3 className="h-4 w-4" /></span><div><p className="text-sm font-bold">Actual measured data</p><p className="text-xs text-slate-500">Manual input for the MVP</p></div></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><Field label="Campaign (optional)"><select value={form.campaignId} onChange={e => set("campaignId", e.target.value)} className="h-9 rounded-md border border-input bg-transparent px-3 text-sm shadow-sm"><option value="">No campaign selected</option>{campaigns.data!.map((campaign: any) => <option value={campaign.id} key={campaign.id}>{campaign.name}</option>)}</select></Field><Field label="Measurement date"><Input required type="date" value={form.metricDate} onChange={e => set("metricDate", e.target.value)} /></Field>{["reach", "impressions", "engagement", "clicks", "leads", "conversions"].map(metric => <Field label={formatLabel(metric)} key={metric}><Input type="number" min="0" value={(form as any)[metric]} onChange={e => set(metric as any, e.target.value)} /></Field>)}<Field label="Spend"><Input type="number" min="0" step="0.01" value={form.spend} onChange={e => set("spend", e.target.value)} /></Field><Field className="sm:col-span-2" label="Notes (optional)"><Textarea value={form.notes} onChange={e => set("notes", e.target.value)} placeholder="Describe the promotion or period measured." /></Field></div><Button disabled={create.isPending} type="submit" className="mt-5 w-full bg-[#0f766e] hover:bg-[#0b625c]">{create.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Save measured data</Button></form><div className="space-y-5"><section className="rounded-3xl border border-blue-100 bg-blue-50/50 p-5"><div className="flex items-start justify-between gap-3"><div><span className="rounded-full bg-blue-100 px-2.5 py-1 text-[11px] font-bold text-blue-800">Actual measured data</span><h3 className="mt-3 text-lg font-bold text-[#071b2e]">Latest recorded performance</h3><p className="mt-1 text-xs text-slate-600">These values are exactly what you entered. No AI-generated estimates are mixed in.</p></div>{latest && <p className="text-xs font-semibold text-slate-500">{formatDate(latest.metricDate)}</p>}</div>{latest ? <><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Reach", latest.reach], ["Impressions", latest.impressions], ["Engagement", latest.engagement], ["Clicks", latest.clicks], ["Leads", latest.leads], ["Conversions", latest.conversions], ["Spend", `$${latest.spend.toLocaleString()}`], ["Eng. rate", `${rates!.engagement.toFixed(1)}%`]].map(([label, value]) => <div key={label as string} className="rounded-xl bg-white p-3"><p className="text-[11px] font-semibold text-slate-500">{label}</p><p className="mt-1 text-lg font-bold text-slate-900">{typeof value === "number" ? compactNumber(value) : value}</p></div>)}</div><p className="mt-4 text-xs text-slate-600"><strong>Calculated rates:</strong> Click rate {rates!.click.toFixed(1)}% · Conversion rate {rates!.conversion.toFixed(1)}%</p></> : <div className="mt-5"><EmptyInline icon={BarChart3} title="No measured data yet" text="Enter observed reach, clicks, leads, or spend before asking for an AI interpretation." /></div>}</section>{latest && <section className="rounded-3xl border border-teal-200 bg-teal-50/60 p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><span className="rounded-full bg-teal-100 px-2.5 py-1 text-[11px] font-bold text-teal-800">AI-generated interpretation</span><h3 className="mt-3 text-lg font-bold text-[#071b2e]">What MASS AI sees in your data</h3><p className="mt-1 text-xs text-slate-600">This is a separate AI interpretation of the raw measurement above, not an additional measured result.</p></div>{!interpretations[latest.id] && <Button disabled={interpret.isPending} onClick={() => interpret.mutate({ insightId: latest.id })} className="shrink-0 bg-[#0f766e] hover:bg-[#0b625c]">{interpret.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Sparkles className="mr-1 h-4 w-4" />}Interpret data</Button>}</div>{interpretations[latest.id] ? <div className="mt-5 grid gap-3"><InsightBlock label="Interpretation" text={interpretations[latest.id].interpretation} /><InsightBlock label="Recommendation" text={interpretations[latest.id].recommendation} /><div className="grid gap-3 sm:grid-cols-2"><PlanList title="How to execute" values={interpretations[latest.id].executionSteps} /><InsightBlock label="Metric to monitor" text={interpretations[latest.id].metricToMonitor} /></div></div> : <div className="mt-5 rounded-xl border border-dashed border-teal-200 bg-white/70 p-4 text-sm text-slate-600">Choose <strong>Interpret data</strong> to ask MASS AI for an actionable reading. It will work only with your stored business context and these actual measurements.</div>}</section>}</div></div><section className="mt-6 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[0.15em] text-slate-500">Measurement history</p><h3 className="mt-1 text-lg font-bold">All raw data entries</h3>{insights.data!.length ? <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b border-slate-100 text-xs text-slate-500"><tr>{["Date", "Reach", "Engagement", "Clicks", "Leads", "Conversions", "Spend"].map(head => <th className="px-3 py-3 font-semibold" key={head}>{head}</th>)}</tr></thead><tbody>{insights.data!.map((item: any) => <tr key={item.id} className="border-b border-slate-50"><td className="px-3 py-3 font-medium">{formatDate(item.metricDate)}</td><td className="px-3 py-3">{compactNumber(item.reach)}</td><td className="px-3 py-3">{compactNumber(item.engagement)}</td><td className="px-3 py-3">{compactNumber(item.clicks)}</td><td className="px-3 py-3">{compactNumber(item.leads)}</td><td className="px-3 py-3">{compactNumber(item.conversions)}</td><td className="px-3 py-3">${item.spend.toLocaleString()}</td></tr>)}</tbody></table></div> : <div className="mt-4"><EmptyInline icon={ClipboardList} title="No history to show" text="Each manual data entry will appear here as raw measured data." /></div>}</section></section>; }
function InsightBlock({ label, text }: { label: string; text: string }) { return <div className="rounded-xl bg-white/80 p-3"><p className="text-xs font-bold text-teal-800">{label}</p><p className="mt-1 text-sm leading-relaxed text-slate-700">{text}</p></div>; }

function BusinessProfile({ profile, onFinished }: { profile: any; onFinished: () => void }) { const [form, setForm] = useState({ businessName: profile.businessName, businessType: profile.businessType, description: profile.description, location: profile.location, targetAudience: profile.targetAudience, marketingGoal: profile.marketingGoal, channels: profile.channels.join(", "), productsServices: profile.productsServices, monthlyBudget: profile.monthlyBudget?.toString() || "", websiteUrl: profile.websiteUrl || "", socialLinks: profile.socialLinks || "" }); const save = trpc.mass.business.save.useMutation({ onSuccess: () => { toast.success("Business profile updated."); onFinished(); }, onError: e => toast.error(e.message) }); const set = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value })); const submit = (e: React.FormEvent) => { e.preventDefault(); const channels = form.channels.split(",").map((item: string) => item.trim()).filter(Boolean); if (!channels.length) return toast.error("Add at least one channel."); save.mutate({ ...form, channels, monthlyBudget: numberOrNull(form.monthlyBudget), websiteUrl: form.websiteUrl || null, socialLinks: form.socialLinks || null }); }; return <section><PageHeading eyebrow="Business profile" title="Keep MASS AI’s business context current" description="This profile is the grounding information used by MASS AI across campaign planning, content generation, guidance, and insights." /><form onSubmit={submit} className="mt-6 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm md:p-6"><div className="grid gap-4 sm:grid-cols-2"><Field label="Business name"><Input required value={form.businessName} onChange={e => set("businessName", e.target.value)} /></Field><Field label="Business type"><Input required value={form.businessType} onChange={e => set("businessType", e.target.value)} /></Field><Field label="Location"><Input required value={form.location} onChange={e => set("location", e.target.value)} /></Field><Field label="Main marketing goal"><Input required value={form.marketingGoal} onChange={e => set("marketingGoal", e.target.value)} /></Field><Field className="sm:col-span-2" label="Business description"><Textarea required value={form.description} onChange={e => set("description", e.target.value)} /></Field><Field className="sm:col-span-2" label="Products and services"><Textarea required value={form.productsServices} onChange={e => set("productsServices", e.target.value)} /></Field><Field className="sm:col-span-2" label="Target audience"><Input required value={form.targetAudience} onChange={e => set("targetAudience", e.target.value)} /></Field><Field label="Preferred channels"><Input required value={form.channels} onChange={e => set("channels", e.target.value)} /></Field><Field label="Monthly budget (optional)"><Input type="number" min="0" value={form.monthlyBudget} onChange={e => set("monthlyBudget", e.target.value)} /></Field><Field label="Website (optional)"><Input type="url" value={form.websiteUrl} onChange={e => set("websiteUrl", e.target.value)} /></Field><Field label="Social links (optional)"><Input value={form.socialLinks} onChange={e => set("socialLinks", e.target.value)} /></Field></div><div className="mt-6 flex justify-end"><Button disabled={save.isPending} className="bg-[#0f766e] hover:bg-[#0b625c]">{save.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}<Save className="mr-1 h-4 w-4" />Save profile</Button></div></form></section>; }
function SettingsView({ onProfile }: { onProfile: () => void }) { const { user, logout } = useAuth(); const summary = trpc.mass.dashboard.summary.useQuery(); return <section><PageHeading eyebrow="Settings" title="Account and workspace settings" description="MASS AI does not show simulated billing information. Trial details are calculated from your actual account creation date." /><div className="mt-6 grid gap-5 lg:grid-cols-2"><section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[0.14em] text-slate-500">Account</p><div className="mt-4 flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-full bg-slate-100 font-bold text-slate-700">{(user?.name || "U").slice(0, 1).toUpperCase()}</div><div><p className="font-bold">{user?.name || "Business owner"}</p><p className="text-sm text-slate-500">{user?.email || "Signed in through Manus OAuth"}</p></div></div><div className="mt-5 flex flex-wrap gap-2"><Button variant="outline" onClick={onProfile}><UserRound className="mr-1 h-4 w-4" />Edit business profile</Button><Button variant="outline" className="text-red-700 hover:bg-red-50" onClick={logout}><LogOut className="mr-1 h-4 w-4" />Sign out</Button></div></section><section className="rounded-3xl border border-teal-200 bg-teal-50 p-5"><p className="text-xs font-bold uppercase tracking-[0.14em] text-teal-800">14-day trial</p>{summary.data ? <><p className="mt-3 text-2xl font-bold text-[#071b2e]">{summary.data.trial.status}</p><p className="mt-1 text-sm text-teal-900">{summary.data.trial.daysRemaining} day{summary.data.trial.daysRemaining === 1 ? "" : "s"} remaining</p><div className="mt-5 grid grid-cols-2 gap-3 border-t border-teal-200 pt-4"><div><p className="text-[11px] font-bold text-teal-800">START DATE</p><p className="mt-1 text-sm font-semibold text-slate-800">{formatDate(summary.data.trial.startDate)}</p></div><div><p className="text-[11px] font-bold text-teal-800">END DATE</p><p className="mt-1 text-sm font-semibold text-slate-800">{formatDate(summary.data.trial.endDate)}</p></div></div></> : <Loader2 className="mt-4 h-5 w-5 animate-spin text-teal-700" />}</section></div><section className="mt-5 rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><p className="text-sm font-bold">Subscription and payment</p><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-600">Payment integration is not configured in this MVP. MASS AI intentionally does not display a fabricated subscription status, payment history, or billing plan.</p></section></section>; }
